#include <set>
#include <iostream>

template<typename T>
struct RuntimeCmp {
    enum mode_t { normal, reverse };
    mode_t mode = normal;
    RuntimeCmp(mode_t m = normal) : mode(m) {}

    bool operator()(const T& a, const T& b) const {
        return (mode == normal) ? (a < b) : (a > b);
    }
};

using IntSet = std::set<int, RuntimeCmp<int>>;

int main() {
    // Configure for reverse ordering at construction
    RuntimeCmp<int> reverse_cfg(RuntimeCmp<int>::reverse);
    IntSet coll(reverse_cfg); 
    coll.insert(5); coll.insert(1);
    // Output: 5 1 (Reverse order)
    for (int x : coll) std::cout << x << " ";
}
